package es.uma.urbanpulse.shared.storage;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.UUID;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * {@link LocalFsStorage} through {@link StorageService}, on a temporary folder (ADR-0013). Covers
 * the storage side of #67: T1 (the file survives a restart), T7 (the key is generated by the
 * server) and T12 (a provider failure is a {@link StorageException}).
 */
class LocalFsStorageTest {

    private static final byte[] PHOTO =
            "a photo of a broken street light".getBytes(StandardCharsets.UTF_8);

    @TempDir Path basePath;

    private StorageService storage() {
        return new LocalFsStorage(basePath);
    }

    @Test
    void returnsTheStoredContent() {
        var storage = storage();

        var key = storage.put(PHOTO);

        assertThat(storage.get(key)).isEqualTo(PHOTO);
    }

    @Test
    void generatesANewUuidKeyForEveryPutEvenWithTheSameContent() {
        var storage = storage();

        var first = storage.put(PHOTO);
        var second = storage.put(PHOTO);

        assertThat(first).isNotEqualTo(second);
        assertThat(UUID.fromString(first).toString()).isEqualTo(first);
        assertThat(UUID.fromString(second).toString()).isEqualTo(second);
    }

    @Test
    void keepsTheContentAfterARestart() {
        var key = storage().put(PHOTO);

        var afterRestart = new LocalFsStorage(basePath);

        assertThat(afterRestart.get(key)).isEqualTo(PHOTO);
    }

    @Test
    void createsTheBaseFolderWhenItDoesNotExistYet() {
        var storage = new LocalFsStorage(basePath.resolve("evidence"));

        var key = storage.put(PHOTO);

        assertThat(storage.get(key)).isEqualTo(PHOTO);
    }

    @Test
    void existsOnlyForStoredKeys() {
        var storage = storage();

        var key = storage.put(PHOTO);

        assertThat(storage.exists(key)).isTrue();
        assertThat(storage.exists(UUID.randomUUID().toString())).isFalse();
    }

    @Test
    void deleteRemovesTheContent() {
        var storage = storage();
        var key = storage.put(PHOTO);

        storage.delete(key);

        assertThat(storage.exists(key)).isFalse();
    }

    @Test
    void deletingAnUnknownKeyIsNotAnError() {
        var storage = storage();
        var unknown = UUID.randomUUID().toString();

        storage.delete(unknown);

        assertThat(storage.exists(unknown)).isFalse();
    }

    @Test
    void readingAKeyWithoutContentIsAStorageFailure() {
        var storage = storage();

        assertThatThrownBy(() -> storage.get(UUID.randomUUID().toString()))
                .isInstanceOf(StorageException.class);
    }

    @Test
    void refusesKeysItCouldNotHaveGenerated() throws IOException {
        Files.writeString(basePath.getParent().resolve("outside.txt"), "secret");
        var storage = storage();

        for (var key : new String[] {"../outside.txt", "outside.txt", "", "a/b"}) {
            assertThatThrownBy(() -> storage.get(key))
                    .as("get(%s)", key)
                    .isInstanceOf(IllegalArgumentException.class);
            assertThatThrownBy(() -> storage.exists(key))
                    .as("exists(%s)", key)
                    .isInstanceOf(IllegalArgumentException.class);
            assertThatThrownBy(() -> storage.delete(key))
                    .as("delete(%s)", key)
                    .isInstanceOf(IllegalArgumentException.class);
        }
    }

    @Test
    void aFolderThatCannotBeWrittenIsAStorageFailure() throws IOException {
        var notAFolder = Files.writeString(basePath.resolve("not-a-folder"), "a file");
        var storage = new LocalFsStorage(notAFolder);

        assertThatThrownBy(() -> storage.put(PHOTO)).isInstanceOf(StorageException.class);
    }
}
